const FLASH_DATA={"topics": [{"id": 0, "title": "第一單元 第一課 世界地圖與臺灣位置", "source": "課本第14至17頁", "unit": "1"}, {"id": 1, "title": "第一單元 第一課 季風與生活適應", "source": "課本第18至19頁", "unit": "1"}, {"id": 2, "title": "第一單元 第一課 洋流與候鳥", "source": "課本第20至21頁", "unit": "1"}, {"id": 3, "title": "第一單元 第二課 史前時代與舊石器生活", "source": "課本第22至23頁", "unit": "1"}, {"id": 4, "title": "第一單元 第二課 新石器與金屬器發展", "source": "課本第24至25頁", "unit": "1"}, {"id": 5, "title": "第一單元 第二課 器物交流與文物線索", "source": "課本第26至28頁", "unit": "1"}, {"id": 6, "title": "第一單元 第三課 族群文化與神話", "source": "課本第29至31頁", "unit": "1"}, {"id": 7, "title": "第一單元 第三課 部落生活與生態智慧", "source": "課本第32至33頁", "unit": "1"}, {"id": 8, "title": "第二單元 第一課 大航海與海上貿易", "source": "課本第38至39頁", "unit": "2"}, {"id": 9, "title": "第二單元 第一課 荷蘭與西班牙據點", "source": "課本第40至43頁", "unit": "2"}, {"id": 10, "title": "第二單元 第一課 鄭氏政權與時間順序", "source": "課本第44至45頁", "unit": "2"}, {"id": 11, "title": "第二單元 第二課 宗教文字與生活影響", "source": "課本第46至47頁", "unit": "2"}, {"id": 12, "title": "第二單元 第二課 屯墾貿易文教與信仰", "source": "課本第48至51頁", "unit": "2"}, {"id": 13, "title": "補充閱讀 臺灣玉與大肚王國", "source": "課本第34至35頁及第52至53頁", "unit": "extra"}, {"id": 14, "title": "跨課整合 易混淆重點填空", "source": "第一及第二單元綜合", "unit": "mixed"}], "questions": [{"id": 1, "topic": 0, "text": "課本將世界陸地分成五大洲，分別為{{亞洲}}、{{歐洲}}、{{美洲}}、{{非洲}}與{{大洋洲}}。", "blanks": 5}, {"id": 2, "topic": 0, "text": "環繞陸地、彼此相通的三大洋，是{{太平洋}}、{{大西洋}}與{{印度洋}}。", "blanks": 3}, {"id": 3, "topic": 0, "text": "從世界地圖看，臺灣位於{{亞洲}}的東側、{{太平洋}}的西側。", "blanks": 2}, {"id": 4, "topic": 0, "text": "臺灣西側與中國之間的海域，稱為{{臺灣海峽}}。", "blanks": 1}, {"id": 5, "topic": 0, "text": "觀察課本地圖，臺灣北方鄰近{{日本}}，南方鄰近{{菲律賓}}。（填國名）", "blanks": 2}, {"id": 7, "topic": 0, "text": "四百多年前，歐洲國家憑藉{{航海}}技術進步，積極向海外探險。", "blanks": 1}, {"id": 8, "topic": 0, "text": "早期航海活動促進世界地圖成為{{航海}}與{{貿易}}的工具。", "blanks": 2}, {"id": 10, "topic": 0, "text": "早期歐洲航行者看到臺灣風景美麗，稱臺灣為{{福爾摩沙}}，外文寫作{{Formosa}}。", "blanks": 2}, {"id": 11, "topic": 0, "text": "臺灣四面環{{海}}、位置適中，可以透過航運與東亞各國進行{{交流}}或{{貿易}}。", "blanks": 3}, {"id": 12, "topic": 0, "text": "臺灣歷史文化的發展，也受到鄰近的{{中國}}與{{日本}}影響。", "blanks": 2}, {"id": 13, "topic": 0, "text": "依課本，我國現有範圍包括臺灣島、{{澎湖群島}}、{{金門群島}}、{{馬祖列島}}等島嶼。", "blanks": 3}, {"id": 14, "topic": 0, "text": "依課本，我國範圍還包括{{釣魚臺列嶼}}與{{南海諸島}}，陸地面積約{{36000}}平方公里。", "blanks": 3}, {"id": 15, "topic": 0, "text": "利用海洋地理位置的優勢，臺灣發展的產業包括{{航運}}、{{漁業}}與{{觀光}}。", "blanks": 3}, {"id": 17, "topic": 1, "text": "臺灣位於{{亞洲大陸}}與{{太平洋}}的交界處，是季風盛行的區域。", "blanks": 2}, {"id": 18, "topic": 1, "text": "冬季從大陸北方吹來、較寒冷乾燥的風，稱為{{東北季風}}。", "blanks": 1}, {"id": 19, "topic": 1, "text": "冬季季風經過海洋會帶來{{水氣}}，影響臺灣的降雨。", "blanks": 1}, {"id": 20, "topic": 1, "text": "冬季東北季風使臺灣{{北部}}與{{東北部}}地區較濕冷、容易降雨。", "blanks": 2}, {"id": 21, "topic": 1, "text": "夏季影響臺灣、帶來西南方暖溼氣流的季風，稱為{{西南季風}}。", "blanks": 1}, {"id": 22, "topic": 1, "text": "夏季西南季風使臺灣整體呈現較{{多雨}}的情形。", "blanks": 1}, {"id": 23, "topic": 1, "text": "依課本圖示，東北季風主要影響時間約為{{10}}月初至隔年{{4}}月中。", "blanks": 2}, {"id": 24, "topic": 1, "text": "依課本圖示，西南季風主要影響時間約為{{6}}月中至{{9}}月中。", "blanks": 2}, {"id": 25, "topic": 1, "text": "臺灣南部夏天常有大雷雨，冬季降雨量則較{{少}}。", "blanks": 1}, {"id": 26, "topic": 1, "text": "若南部冬季降雨少、又缺乏水源，有些稻田只能{{休耕}}。", "blanks": 1}, {"id": 27, "topic": 1, "text": "面對不同氣候，居民會運用{{在地資源}}，設計適合日常生活的建築與器物。", "blanks": 1}, {"id": 28, "topic": 1, "text": "居民會依當地{{氣候}}與{{土地}}條件，種植適合生長的農作物。", "blanks": 2}, {"id": 29, "topic": 1, "text": "新竹居民利用季風與{{日曬}}，把柿子製成{{柿餅}}，以延長保存期限。", "blanks": 2}, {"id": 30, "topic": 1, "text": "雲林老街房屋的{{騎樓}}設計，可以提供遮陽與避雨的空間。", "blanks": 1}, {"id": 31, "topic": 1, "text": "臺東縣蘭嶼的野銀部落，保有許多傳統{{地下屋}}建築。", "blanks": 1}, {"id": 33, "topic": 2, "text": "臺灣位於{{寒流}}與{{暖流}}交會的地區。", "blanks": 2}, {"id": 34, "topic": 2, "text": "不同季節的洋流會帶來不同的{{魚群}}，影響沿海生活。", "blanks": 1}, {"id": 35, "topic": 2, "text": "冬季時，隨寒流而來並到臺灣西南沿海產卵的魚是{{烏魚}}。", "blanks": 1}, {"id": 37, "topic": 2, "text": "臺灣{{西南}}沿海地區的重要物產之一是烏魚子。（填方位）", "blanks": 1}, {"id": 38, "topic": 2, "text": "春、夏時，隨暖流北上洄游的魚是{{黑鮪魚}}。", "blanks": 1}, {"id": 39, "topic": 2, "text": "依課文，黑鮪魚會在{{日本}}至{{菲律賓}}之間的海域產卵。（填國名）", "blanks": 2}, {"id": 40, "topic": 2, "text": "屏東的黑鮪魚文化觀光季，結合{{漁業}}與{{觀光}}，發展地方特色。", "blanks": 2}, {"id": 41, "topic": 2, "text": "依季節遷移、在不同地區停留的鳥類，稱為{{候鳥}}。", "blanks": 1}, {"id": 42, "topic": 2, "text": "黑面琵鷺每年秋天會從{{北方}}飛來臺灣度冬。（填方向）", "blanks": 1}, {"id": 43, "topic": 2, "text": "課本指出黑面琵鷺約在每年{{9}}至{{10}}月溫度逐漸下降時南遷。", "blanks": 2}, {"id": 44, "topic": 2, "text": "黑面琵鷺約在隔年{{3}}至{{5}}月離開臺灣、再往北方飛。", "blanks": 2}, {"id": 45, "topic": 2, "text": "臺南七股的{{濕地}}提供黑面琵鷺覓食與棲息的環境。", "blanks": 1}, {"id": 47, "topic": 3, "text": "沒有{{文字}}紀錄的年代，稱為{{史前時代}}。", "blanks": 2}, {"id": 48, "topic": 3, "text": "研究沒有文字紀錄的生活，可以觀察地下發現的{{遺址}}與{{出土文物}}。", "blanks": 2}, {"id": 49, "topic": 3, "text": "史前人類的生活與{{自然環境}}息息相關。", "blanks": 1}, {"id": 50, "topic": 3, "text": "課本依工具與技術介紹史前發展，包括{{舊石器時代}}、{{新石器時代}}與{{金屬器時代}}。", "blanks": 3}, {"id": 52, "topic": 3, "text": "臺灣舊石器時代的例子之一，是臺東的{{長濱文化}}。", "blanks": 1}, {"id": 53, "topic": 3, "text": "長濱文化遺址位於{{臺東縣}}的{{長濱鄉}}。", "blanks": 2}, {"id": 54, "topic": 3, "text": "長濱文化的重要遺址位於{{八仙洞}}。", "blanks": 1}, {"id": 55, "topic": 3, "text": "舊石器時代的人們會住在天然的{{洞穴}}，利用環境庇護自己。", "blanks": 1}, {"id": 56, "topic": 3, "text": "舊石器時代的人們透過{{採集}}取得植物性食物。", "blanks": 1}, {"id": 57, "topic": 3, "text": "除了採集，人們也會透過{{狩獵}}與{{捕魚}}獲取食物。", "blanks": 2}, {"id": 58, "topic": 3, "text": "舊石器時代的人們敲擊石頭製作工具，稱為{{打製石器}}。", "blanks": 1}, {"id": 59, "topic": 3, "text": "當時人們已經知道用{{火}}燒烤食物與取暖。", "blanks": 1}, {"id": 60, "topic": 3, "text": "依課本，將石頭敲擊製成工具、以採集狩獵為主的生活，較符合{{舊石器}}時代。", "blanks": 1}, {"id": 61, "topic": 3, "text": "史前沒有文字紀錄，因此研究者要透過{{考古}}工作推測當時生活。", "blanks": 1}, {"id": 63, "topic": 4, "text": "臺東的{{卑南遺址}}是課本介紹新石器時代的重要例子。", "blanks": 1}, {"id": 64, "topic": 4, "text": "新石器時代的人們會把石頭{{磨製}}，做成更合適的工具。", "blanks": 1}, {"id": 65, "topic": 4, "text": "新石器時代開始發展種植{{芋頭}}與{{稻米}}等作物的農業。", "blanks": 2}, {"id": 66, "topic": 4, "text": "新石器時代用來收割作物的工具之一是{{石刀}}。", "blanks": 1}, {"id": 67, "topic": 4, "text": "新石器時代的人們會使用{{石板}}組成{{石棺}}，反映當時的喪葬生活。", "blanks": 2}, {"id": 68, "topic": 4, "text": "人們開始製作{{陶器}}，用來儲存食物或烹煮。", "blanks": 1}, {"id": 69, "topic": 4, "text": "卑南遺址出土的{{石板棺}}，可以協助研究當時的喪葬生活。", "blanks": 1}, {"id": 70, "topic": 4, "text": "農業與食物儲存發展，使人們較容易{{定居}}，形成聚落。", "blanks": 1}, {"id": 71, "topic": 4, "text": "穩定的生活與食物供應，有助於{{人口}}成長及村落發展。", "blanks": 1}, {"id": 72, "topic": 4, "text": "新石器時代的人們也會飼養{{家畜}}，增加食物來源。", "blanks": 1}, {"id": 73, "topic": 4, "text": "課文介紹新北市{{八里區}}的{{十三行遺址}}，屬於金屬器時代。", "blanks": 2}, {"id": 74, "topic": 4, "text": "十三行遺址的人們學會由{{海外}}傳入的{{煉鐵}}及製造鐵器技術。", "blanks": 2}, {"id": 75, "topic": 4, "text": "金屬器時代的人們除了使用鐵製工具，也利用{{鐵刀}}耕作，提高生產能力。", "blanks": 1}, {"id": 77, "topic": 4, "text": "鐵器、農業與專業工作的發展，顯示生活逐漸出現更多{{分工}}。", "blanks": 1}, {"id": 78, "topic": 4, "text": "比較三個時代的工具，主要技術依序可寫成打製石器、{{磨製石器}}與{{製造鐵器}}。", "blanks": 2}, {"id": 79, "topic": 5, "text": "新石器時代以來，隨著{{農業}}生產增加，聚落之間的物品交換也增加。", "blanks": 1}, {"id": 80, "topic": 5, "text": "新石器時代，花蓮出產的{{臺灣玉}}，是製作玉器的重要材料。", "blanks": 1}, {"id": 81, "topic": 5, "text": "在其他地區發現臺灣玉製品，可以作為聚落間{{交流}}的線索。", "blanks": 1}, {"id": 82, "topic": 5, "text": "十三行遺址出土來自東南亞的{{琉璃珠}}，是課文介紹的外來交流物品之一。", "blanks": 1}, {"id": 83, "topic": 5, "text": "課文指出，臺灣史前玉器也曾出現在{{東南亞}}地區，呈現跨海交流。", "blanks": 1}, {"id": 84, "topic": 5, "text": "花蓮的臺灣玉在卑南等多處遺址出現，顯示新石器時代臺灣島內已有器物{{交換活動}}。", "blanks": 1}, {"id": 85, "topic": 5, "text": "來自海外的物品，顯示當時人們可能具備{{航海}}技術或進行跨海交易。", "blanks": 1}, {"id": 86, "topic": 5, "text": "課本介紹卑南遺址的{{人獸形玉器}}，是玉器工藝的例子。", "blanks": 1}, {"id": 87, "topic": 5, "text": "課本以玉器與{{琉璃珠}}作為「傳播千里的器物交流」例子。", "blanks": 1}, {"id": 88, "topic": 5, "text": "第28頁介紹十三行文化博物館的代表文物是{{人面陶罐}}。", "blanks": 1}, {"id": 89, "topic": 5, "text": "第28頁介紹花蓮縣考古博物館的文物是{{月眉石槽}}。", "blanks": 1}, {"id": 90, "topic": 5, "text": "第28頁介紹臺南左鎮化石園區的展品是{{左鎮人頭骨化石}}。", "blanks": 1}, {"id": 93, "topic": 6, "text": "依課本說明，臺灣原住民族祖先很可能早在{{史前時代}}就已遷徙到臺灣。", "blanks": 1}, {"id": 94, "topic": 6, "text": "依本課課本列示，政府認定的原住民族共有{{16}}族。", "blanks": 1}, {"id": 95, "topic": 6, "text": "原住民族透過{{神話傳說}}、{{歌謠}}與{{祭典}}等方式傳承文化。", "blanks": 3}, {"id": 96, "topic": 6, "text": "族群神話不只展現多元文化，也記錄族群起源與早期和{{自然}}共存的生活。", "blanks": 1}, {"id": 97, "topic": 6, "text": "課文的白鹿傳說，屬於{{邵族}}的文化故事。", "blanks": 1}, {"id": 98, "topic": 6, "text": "邵族白鹿傳說呈現先民依據{{自然資源}}遷徙與選擇定居地的過程。", "blanks": 1}, {"id": 99, "topic": 6, "text": "依第29頁分布示意圖，邵族的主要分布區域位於{{南投}}一帶。", "blanks": 1}, {"id": 100, "topic": 6, "text": "雅美族又稱{{達悟族}}，課本以括號並列這兩個名稱。", "blanks": 1}, {"id": 101, "topic": 6, "text": "雅美族（達悟族）的傳統文化與{{海洋}}環境密切相關。", "blanks": 1}, {"id": 102, "topic": 6, "text": "課文提到雅美族（達悟族）神話中，{{飛魚之神}}教導族人正確食用飛魚的方法與禮儀。", "blanks": 1}, {"id": 103, "topic": 6, "text": "雅美族（達悟族）依循季節捕魚，避免人類{{大量捕食}}造成飛魚減少。", "blanks": 1}, {"id": 104, "topic": 6, "text": "課文以飛魚文化說明，先民已經具有{{生態保育}}的智慧。", "blanks": 1}, {"id": 105, "topic": 6, "text": "課本圖說指出，雅美族（達悟族）捕飛魚時不將飛魚一網打盡，能讓飛魚持續{{繁衍}}。", "blanks": 1}, {"id": 106, "topic": 6, "text": "神話傳說屬於文化傳承；研究史前實物，則可以透過{{考古}}尋找證據。", "blanks": 1}, {"id": 107, "topic": 6, "text": "依第29頁分布圖，雅美族（達悟族）分布於臺灣東南方的{{蘭嶼}}。", "blanks": 1}, {"id": 109, "topic": 7, "text": "早期原住民族生活的中心是{{部落}}，通常由許多家族組成。", "blanks": 1}, {"id": 110, "topic": 7, "text": "部落的祭典、狩獵及禁忌等重要事務，有些由{{頭目}}或祭司決定。", "blanks": 1}, {"id": 111, "topic": 7, "text": "有些部落的重要事務，會由{{部落會議}}決議。", "blanks": 1}, {"id": 113, "topic": 7, "text": "原住民族將祖先傳承的{{山林知識}}運用在狩獵生活中。", "blanks": 1}, {"id": 114, "topic": 7, "text": "狩獵禁忌與傳統知識，有助維持{{生態平衡}}。", "blanks": 1}, {"id": 115, "topic": 7, "text": "課本介紹泰雅族的歲時祭儀，主要與{{狩獵}}及{{農業生產}}相關。", "blanks": 2}, {"id": 116, "topic": 7, "text": "泰雅族舉行小米祈福祭儀時，會由{{頭目}}為族人祈福。", "blanks": 1}, {"id": 117, "topic": 7, "text": "課文介紹泰雅族在山林狩獵時，不可獵捕{{幼小}}的動物。", "blanks": 1}, {"id": 118, "topic": 7, "text": "依課本案例，泰雅族約在{{11}}月至隔年{{4}}月間狩獵，以避開動物繁殖較多的時期。", "blanks": 2}, {"id": 119, "topic": 7, "text": "泰雅族利用{{竹子}}取水、引水及製作食器。", "blanks": 1}, {"id": 120, "topic": 7, "text": "除了竹子，泰雅族也利用{{木頭}}建造房屋。", "blanks": 1}, {"id": 121, "topic": 7, "text": "泰雅族有{{共食團體}}，會分享獵物與食物。", "blanks": 1}, {"id": 122, "topic": 7, "text": "族人分工合作，為族人結婚或建造房屋等事務提供協助，展現{{互助}}精神。", "blanks": 1}, {"id": 124, "topic": 7, "text": "利用環境中的材料製作器物與建築，稱為{{就地取材}}。", "blanks": 1}, {"id": 125, "topic": 8, "text": "西元{{16}}世紀，歐洲國家積極從事海外探險。", "blanks": 1}, {"id": 126, "topic": 8, "text": "歐洲人前往亞洲，希望尋找{{瓷器}}、{{絲綢}}與{{香料}}等商品。", "blanks": 3}, {"id": 127, "topic": 8, "text": "歐洲人帶動亞洲的海上貿易交流，並逐步發展進入{{大航海時代}}。", "blanks": 1}, {"id": 128, "topic": 8, "text": "大航海時代各地因{{海上貿易}}往來，增加互動與接觸。", "blanks": 1}, {"id": 129, "topic": 8, "text": "臺灣位於{{東亞}}重要交通位置，因此逐漸受到國際注意。", "blanks": 1}, {"id": 130, "topic": 8, "text": "歐洲人來臺前，臺灣已有{{原住民族}}居住生活。", "blanks": 1}, {"id": 131, "topic": 8, "text": "當時已有{{漢人}}到臺灣捕魚，並與原住民族交換物品。", "blanks": 1}, {"id": 132, "topic": 8, "text": "由{{中國}}與{{日本}}等地來的海商、海盜，也曾在臺灣一帶活動。", "blanks": 2}, {"id": 133, "topic": 8, "text": "依課文傳說，與鄭芝龍等人到笨港一帶開墾的海上人物之一是{{顏思齊}}。", "blanks": 1}, {"id": 134, "topic": 8, "text": "顏思齊等人活動的笨港，位在今天的{{雲林}}與{{嘉義}}一帶。", "blanks": 2}, {"id": 135, "topic": 8, "text": "讀航線圖時，可以從貨物流動了解地區之間的{{貿易}}關係。", "blanks": 1}, {"id": 136, "topic": 8, "text": "臺灣登上國際舞臺的重要條件之一，是它的{{地理位置}}。", "blanks": 1}, {"id": 137, "topic": 9, "text": "歐洲國家到東亞競爭貿易，臺灣逐漸成為{{荷蘭}}與{{西班牙}}等勢力競逐的對象。", "blanks": 2}, {"id": 138, "topic": 9, "text": "荷蘭人在亞洲先於{{印尼}}設立據點。（填今日國名簡稱）", "blanks": 1}, {"id": 139, "topic": 9, "text": "荷蘭人於西元{{1624}}年來到臺灣南部。", "blanks": 1}, {"id": 140, "topic": 9, "text": "荷蘭人以{{臺南}}為根據地，作為行政管理與商業中心。", "blanks": 1}, {"id": 141, "topic": 9, "text": "荷蘭人在今臺南安平一帶興建{{熱蘭遮城}}。", "blanks": 1}, {"id": 142, "topic": 9, "text": "荷蘭人在今臺南赤崁一帶興建{{普羅民遮城}}。", "blanks": 1}, {"id": 143, "topic": 9, "text": "普羅民遮城的部分遺構，與今日的{{赤崁樓}}歷史有關。", "blanks": 1}, {"id": 144, "topic": 9, "text": "荷蘭人從中國招募{{漢人}}到臺灣開墾農田。", "blanks": 1}, {"id": 145, "topic": 9, "text": "荷蘭人將臺灣的{{蔗糖}}與{{鹿皮}}等商品運往其他地區。", "blanks": 2}, {"id": 146, "topic": 9, "text": "荷蘭人也將絲織品、{{鐵器}}與香料等帶來交換，促進商品貿易。", "blanks": 1}, {"id": 147, "topic": 9, "text": "西班牙人在東亞海域貿易，先以{{菲律賓}}為主要據點。", "blanks": 1}, {"id": 148, "topic": 9, "text": "西班牙人於西元{{1626}}年進入臺灣北部。", "blanks": 1}, {"id": 149, "topic": 9, "text": "西班牙人在今天的{{基隆}}與{{淡水}}建立據點。", "blanks": 2}, {"id": 150, "topic": 9, "text": "西班牙人在基隆和平島建立{{聖薩爾瓦多城}}。", "blanks": 1}, {"id": 151, "topic": 9, "text": "西班牙人在淡水興建{{聖多明哥城}}；後來荷蘭人重建的城堡與今日{{紅毛城}}的歷史有關。", "blanks": 2}, {"id": 152, "topic": 9, "text": "西班牙人貿易不如預期、經費與兵力縮減後，荷蘭人在西元{{1642}}年攻打並驅逐西班牙人。", "blanks": 1}, {"id": 153, "topic": 10, "text": "荷蘭人在臺灣活動期間，中國正值{{明帝國}}滅亡、{{清帝國}}建立的時期。", "blanks": 2}, {"id": 154, "topic": 10, "text": "部分不願投降清朝的軍民，跟隨{{鄭成功}}，在中國東南沿海發展。", "blanks": 1}, {"id": 155, "topic": 10, "text": "鄭成功因軍事接連受挫，決定率軍移到{{臺灣}}。", "blanks": 1}, {"id": 156, "topic": 10, "text": "鄭成功渡海來臺的課本路線，從{{金門}}出發，經過{{澎湖}}。", "blanks": 2}, {"id": 157, "topic": 10, "text": "鄭成功最後在臺灣的{{鹿耳門}}登陸，該地位於今天的{{臺南}}。", "blanks": 2}, {"id": 158, "topic": 10, "text": "鄭成功率軍來臺後，荷蘭人於西元{{1662}}年退出臺灣。", "blanks": 1}, {"id": 159, "topic": 10, "text": "鄭成功來臺後，在臺南設立{{承天府}}。", "blanks": 1}, {"id": 160, "topic": 10, "text": "鄭成功以{{赤崁樓}}一帶作為行政中心，成為早期重要的漢人政權。", "blanks": 1}, {"id": 161, "topic": 10, "text": "鄭成功病逝後，由兒子{{鄭經}}在部將{{陳永華}}輔佐下繼續經營臺灣。", "blanks": 2}, {"id": 162, "topic": 10, "text": "鄭經過世後，內部因爭奪{{政權}}而紛爭不斷。", "blanks": 1}, {"id": 163, "topic": 10, "text": "清帝國趁鄭氏政權內部紛爭的機會，派{{施琅}}帶兵進攻。", "blanks": 1}, {"id": 164, "topic": 10, "text": "依課文，臺灣在西元{{1684}}年正式納入清帝國版圖。", "blanks": 1}, {"id": 165, "topic": 10, "text": "依先後順序，三個來臺發展的勢力是荷蘭人、西班牙人、{{鄭氏政權}}。", "blanks": 1}, {"id": 166, "topic": 10, "text": "把年份由早到晚排列，依序是1624、1626、1642、1662、{{1684}}。", "blanks": 1}, {"id": 168, "topic": 11, "text": "荷蘭人除了獲取商業利益，也在臺灣傳播{{基督教}}。", "blanks": 1}, {"id": 169, "topic": 11, "text": "西班牙傳教士曾在基隆的{{和平島}}建立{{教堂}}，向原住民族傳播天主教。", "blanks": 2}, {"id": 170, "topic": 11, "text": "荷蘭人為傳教設立{{教堂}}與{{學校}}，並學習當地原住民族語言。", "blanks": 2}, {"id": 171, "topic": 11, "text": "荷蘭人利用{{羅馬字母}}拼寫原住民族語言。", "blanks": 1}, {"id": 172, "topic": 11, "text": "傳教士留下的族語書寫資料，有助了解當時的{{語言}}與文化。", "blanks": 1}, {"id": 174, "topic": 11, "text": "荷蘭人離臺一百多年後，原住民與漢人簽訂土地{{契約}}時，仍持續使用羅馬字母。", "blanks": 1}, {"id": 175, "topic": 11, "text": "荷蘭人引進{{黃牛}}，協助農田耕作。", "blanks": 1}, {"id": 176, "topic": 11, "text": "課文介紹荷蘭人引進的{{豌豆}}，又稱荷蘭豆。", "blanks": 1}, {"id": 177, "topic": 11, "text": "課本圖片介紹，荷蘭人引進的水果之一是{{土芒果}}。", "blanks": 1}, {"id": 178, "topic": 11, "text": "西班牙人將臺灣東北角海岬命名為{{San Tiago}}，成為今日{{三貂角}}地名的由來。", "blanks": 2}, {"id": 179, "topic": 11, "text": "考古發現的{{十字架}}，可作為研究西班牙人在北臺灣傳教的線索。", "blanks": 1}, {"id": 180, "topic": 11, "text": "大航海時代的影響，不只有政治與貿易，也包括宗教、{{語言}}、{{物種}}與地名。", "blanks": 2}, {"id": 181, "topic": 12, "text": "鄭氏政權為解決{{糧食}}需求，派軍隊到各地從事農業活動。", "blanks": 1}, {"id": 182, "topic": 12, "text": "軍隊駐紮與開墾，留下如臺南新營、柳營及高雄{{左營}}、{{前鎮}}等地名。", "blanks": 2}, {"id": 184, "topic": 12, "text": "鄭氏政權進口{{民生}}與{{軍火}}物資，以供生活與軍事需要。", "blanks": 2}, {"id": 185, "topic": 12, "text": "鄭氏政權出口{{蔗糖}}與{{鹿皮}}等商品，獲取利益。", "blanks": 2}, {"id": 186, "topic": 12, "text": "鄭氏政權的海外貿易，有助維持{{統治}}與{{經濟發展}}的需求。", "blanks": 2}, {"id": 187, "topic": 12, "text": "依課文，鄭氏時期輸出的鹿皮等商品，也會運往{{日本}}。（填國名）", "blanks": 1}, {"id": 188, "topic": 12, "text": "鄭經在{{陳永華}}輔佐下推動文教建設。", "blanks": 1}, {"id": 189, "topic": 12, "text": "鄭氏政權在{{臺南}}興建全臺第一座孔廟。（填城市）", "blanks": 1}, {"id": 190, "topic": 12, "text": "臺南孔廟又有{{全臺首學}}的稱號。", "blanks": 1}, {"id": 191, "topic": 12, "text": "鄭氏政權設立{{學校}}，並選拔人才管理地方事務。", "blanks": 1}, {"id": 192, "topic": 12, "text": "漢人來臺除了開墾與貿易，也把故鄉的{{習俗}}帶到臺灣。", "blanks": 1}, {"id": 193, "topic": 12, "text": "漢人移民帶來{{玄天上帝}}與{{媽祖}}等信仰，並建立廟宇。", "blanks": 2}, {"id": 194, "topic": 12, "text": "荷蘭人與鄭氏政權持續招募漢人開墾，使臺灣漢人{{人口}}增加。", "blanks": 1}, {"id": 195, "topic": 12, "text": "課文指出，鄭氏政權推行漢人的教育與文化，為臺灣{{漢人社會}}的發展建立基礎。", "blanks": 1}, {"id": 197, "topic": 13, "text": "補充閱讀以{{臺灣玉}}說明史前島內與海外的交流。", "blanks": 1}, {"id": 198, "topic": 13, "text": "位於今日臺東市南王里的重要遺址，稱為{{卑南遺址}}。", "blanks": 1}, {"id": 199, "topic": 13, "text": "卑南遺址出土大量石板棺，也出土玉器與{{陶器}}等文物。", "blanks": 1}, {"id": 200, "topic": 13, "text": "人獸形耳飾以{{玉}}製作，呈現史前人的工藝與審美。", "blanks": 1}, {"id": 201, "topic": 13, "text": "臺灣玉不只在島內流通，也傳到海外的{{東南亞}}等地區。", "blanks": 1}, {"id": 202, "topic": 13, "text": "在其他地區找到來源相同的玉料或玉器，是研究史前{{交流網絡}}的線索。", "blanks": 1}, {"id": 203, "topic": 13, "text": "補充閱讀的大肚王國，主要位於臺灣{{中部}}一帶。", "blanks": 1}, {"id": 204, "topic": 13, "text": "課文介紹的大肚王國，是跨部落的{{聯盟}}，不能直接當成現代國家制度。", "blanks": 1}, {"id": 205, "topic": 13, "text": "大肚王國的居民生活在清水平原與{{大肚台地}}一帶。", "blanks": 1}, {"id": 207, "topic": 13, "text": "漢人增加、土地開墾與軍事進入，可能造成原住民族{{土地}}及生活空間受到壓迫。", "blanks": 1}, {"id": 208, "topic": 13, "text": "探究大肚王國歷史，除了外來政權的紀錄，也應重視{{原住民族}}的立場。", "blanks": 1}, {"id": 209, "topic": 14, "text": "長濱文化位於臺東，屬{{舊石器}}時代；卑南文化屬{{新石器}}時代；十三行文化屬{{金屬器}}時代。", "blanks": 3}, {"id": 210, "topic": 14, "text": "打製石器主要靠{{敲擊}}成形；磨製石器則經過{{磨製}}，工具加工技術不同。", "blanks": 2}, {"id": 211, "topic": 14, "text": "冬季主要是{{東北季風}}影響臺灣；夏季則以{{西南季風}}帶來暖溼氣流。", "blanks": 2}, {"id": 212, "topic": 14, "text": "隨寒流來的魚是{{烏魚}}；課文介紹隨暖流北上的是{{黑鮪魚}}。", "blanks": 2}, {"id": 213, "topic": 14, "text": "邵族的故事線索是{{白鹿}}；雅美族（達悟族）的文化線索是{{飛魚}}。", "blanks": 2}, {"id": 214, "topic": 14, "text": "荷蘭人主要據點在臺灣{{南部}}；西班牙人的主要據點在{{北部}}。", "blanks": 2}, {"id": 215, "topic": 14, "text": "熱蘭遮城位在臺南{{安平}}；聖薩爾瓦多城位在基隆{{和平島}}。", "blanks": 2}, {"id": 216, "topic": 14, "text": "荷蘭人來臺年份為{{1624}}；西班牙人來臺為{{1626}}；荷蘭人退出臺灣為{{1662}}。", "blanks": 3}, {"id": 217, "topic": 14, "text": "荷蘭人在{{1642}}年驅逐西班牙人；{{鄭成功}}後來率軍使荷蘭人退出臺灣。", "blanks": 2}, {"id": 218, "topic": 14, "text": "荷蘭人傳播{{基督教}}，西班牙人傳播{{天主教}}。", "blanks": 2}, {"id": 219, "topic": 14, "text": "原住民與漢人簽訂土地契約時，使用{{羅馬字母}}書寫；三貂角地名與{{西班牙}}人的命名有關。", "blanks": 2}, {"id": 220, "topic": 14, "text": "孔廟文教建設與{{陳永華}}協助鄭經推動政策有關，不是荷蘭人設立的傳教學校。", "blanks": 1}, {"id": 222, "topic": 14, "text": "由舊石器採集狩獵到新石器農業聚落，可以看出人類取得食物及使用{{工具}}的方式會改變。", "blanks": 1}, {"id": 223, "topic": 14, "text": "原住民族的狩獵規範與飛魚文化，都反映人與{{自然環境}}互動及維持生態的智慧。", "blanks": 1}]};